import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Performance Optimization Playbook","description":"Engineering playbook for performance optimization workflow","frontmatter":{"title":"Performance Optimization Playbook","description":"Engineering playbook for performance optimization workflow"},"headers":[],"relativePath":"playbooks/performance-optimization.md","filePath":"playbooks/performance-optimization.md","lastUpdated":1784485118000}'),s={name:"playbooks/performance-optimization.md"};function r(o,e,l,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="performance-optimization-playbook" tabindex="-1">Performance Optimization Playbook <a class="header-anchor" href="#performance-optimization-playbook" aria-label="Permalink to &quot;Performance Optimization Playbook&quot;">​</a></h1><h1 id="playbook-performance-optimization" tabindex="-1">Playbook: Performance Optimization <a class="header-anchor" href="#playbook-performance-optimization" aria-label="Permalink to &quot;Playbook: Performance Optimization&quot;">​</a></h1><p><strong>Goal:</strong> Identify and resolve performance bottlenecks in frontend, backend, or database.</p><p><strong>Trigger:</strong> Slow page load, high API latency, large bundle size, poor Core Web Vitals.</p><p><strong>Inputs:</strong></p><ul><li>Performance metric or complaint</li><li>Affected area (page, API endpoint, database query)</li><li>Baseline measurement (if available)</li></ul><p><strong>Outputs:</strong></p><ul><li>Performance analysis report</li><li>Optimizations implemented</li><li>Before/after measurements</li><li>Prevention guidelines</li></ul><p>----|------| | <code>performance</code> | Primary analyst — bundle, Core Web Vitals, caching | | <code>frontend</code> | Client-side optimization — components, rendering | | <code>backend</code> | Server-side optimization — API, processing | | <code>database</code> | Query optimization — indexing, N+1, joins | | <code>architect</code> | Structural optimization — architecture decisions | | <code>reviewer</code> | Verify optimizations don&#39;t break functionality |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>web-performance</code></td><td>Always — Core Web Vitals, metrics</td></tr><tr><td><code>caching-strategies</code></td><td>Caching layer optimization</td></tr><tr><td><code>image-optimization</code></td><td>Image-related performance</td></tr><tr><td><code>bundle-optimization</code></td><td>Bundle size reduction</td></tr><tr><td><code>nextjs-performance</code></td><td>Next.js-specific optimizations</td></tr><tr><td><code>react-patterns</code></td><td>React rendering optimization</td></tr><tr><td><code>database-performance</code></td><td>Query optimization</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/performance-check</code></td><td>Always — full performance audit</td></tr><tr><td><code>/review</code></td><td>After optimization — verify no regressions</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-measure-10-min" tabindex="-1">Step 1: Measure (10 min) <a class="header-anchor" href="#step-1-measure-10-min" aria-label="Permalink to &quot;Step 1: Measure (10 min)&quot;">​</a></h3><ol><li><strong>Establish baseline</strong> — Current metrics</li><li><strong>Identify bottleneck</strong> — Where is time spent?</li><li><strong>Categorize</strong> — Frontend? Backend? Database? Network?</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build analysis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check bundle size</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --analyze</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Network timing</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Browser DevTools → Network tab → Waterfall</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Key metrics:</p><ul><li><strong>LCP</strong> (Largest Contentful Paint) — &lt; 2.5s</li><li><strong>FID</strong> (First Input Delay) — &lt; 100ms</li><li><strong>CLS</strong> (Cumulative Layout Shift) — &lt; 0.1</li><li><strong>TTFB</strong> (Time to First Byte) — &lt; 200ms</li><li><strong>Bundle size</strong> — &lt; 200KB initial JS</li></ul><h3 id="step-2-analyze-15-min" tabindex="-1">Step 2: Analyze (15 min) <a class="header-anchor" href="#step-2-analyze-15-min" aria-label="Permalink to &quot;Step 2: Analyze (15 min)&quot;">​</a></h3><p><strong>Frontend analysis:</strong></p><ul><li>Large components → Extract, lazy load</li><li>Unnecessary re-renders → Memoize, optimize state</li><li>Large images → Optimize, lazy load, use next/image</li><li>Missing code splitting → Dynamic imports</li><li>Unused code → Tree shaking, remove dead code</li></ul><p><strong>Backend analysis:</strong></p><ul><li>Slow API routes → Profile, optimize logic</li><li>Missing caching → Add response caching</li><li>Large payloads → Paginate, filter fields</li><li>Synchronous operations → Parallelize</li><li>N+1 queries → Batch or join</li></ul><p><strong>Database analysis:</strong></p><ul><li>Slow queries → EXPLAIN ANALYZE</li><li>Missing indexes → Add targeted indexes</li><li>Full table scans → Add WHERE clauses, indexes</li><li>Large result sets → Paginate</li><li>Missing connection pooling → Add pool</li></ul><h3 id="step-3-optimize-varies" tabindex="-1">Step 3: Optimize (varies) <a class="header-anchor" href="#step-3-optimize-varies" aria-label="Permalink to &quot;Step 3: Optimize (varies)&quot;">​</a></h3><ol><li><strong>Start with highest impact</strong> — Biggest bottleneck first</li><li><strong>One optimization at a time</strong> — Measure after each</li><li><strong>Verify behavior</strong> — Same result, faster</li><li><strong>Don&#39;t over-optimize</strong> — Stop at &quot;good enough&quot;</li></ol><h3 id="step-4-measure-again-10-min" tabindex="-1">Step 4: Measure Again (10 min) <a class="header-anchor" href="#step-4-measure-again-10-min" aria-label="Permalink to &quot;Step 4: Measure Again (10 min)&quot;">​</a></h3><ol><li><strong>Compare metrics</strong> — Before vs after</li><li><strong>Verify improvement</strong> — Measurable gain</li><li><strong>Check regressions</strong> — Nothing got worse</li><li><strong>Document results</strong> — What worked, what didn&#39;t</li></ol><h3 id="step-5-prevent-5-min" tabindex="-1">Step 5: Prevent (5 min) <a class="header-anchor" href="#step-5-prevent-5-min" aria-label="Permalink to &quot;Step 5: Prevent (5 min)&quot;">​</a></h3><ol><li><strong>Add performance budgets</strong> — Prevent regression</li><li><strong>Document patterns</strong> — What optimization worked</li><li><strong>Update project AGENTS.md</strong> — Performance guidelines</li><li><strong>Consider CI checks</strong> — Bundle size limits</li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] Baseline measured before optimization</li><li>[ ] Bottleneck identified with evidence</li><li>[ ] Optimization applied to highest impact first</li><li>[ ] Metrics improved after optimization</li><li>[ ] No functional regressions</li><li>[ ] Build still passes</li><li>[ ] Results documented</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>Measurable performance improvement</li><li>No regressions in functionality or other metrics</li><li>Optimization is maintainable</li><li>Prevention measures in place</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Optimizing without measuring</td><td>Wastes time on non-issues</td><td>Measure first, optimize bottlenecks</td></tr><tr><td>Premature optimization</td><td>Adds complexity for negligible gain</td><td>Only optimize when needed</td></tr><tr><td>Over-memoizing</td><td>Adds memory overhead, complexity</td><td>Memoize only expensive computations</td></tr><tr><td>Lazy loading everything</td><td>Adds loading complexity</td><td>Lazy load only large, non-critical components</td></tr><tr><td>Ignoring server-side</td><td>Client optimization has limits</td><td>Consider SSR/SSG optimizations</td></tr><tr><td>Optimizing for wrong metric</td><td>改善了不重要的指标</td><td>Focus on user-facing metrics</td></tr><tr><td>Not testing after optimization</td><td>Optimizations break things</td><td>Always verify functionality</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>`,44)])])}const g=i(s,[["render",r]]);export{h as __pageData,g as default};
